INSERT INTO faqs (question, answer, active) VALUES
('Can I login with my Google or Facebook account?', 'Yes, we support seamless social logins using Google and Facebook for quick and secure access to your account.', true),
('How can I leave feedback for my delivery partner?', 'After your order is delivered, you can rate your delivery experience and leave specific feedback for the delivery partner from your Orders page.', true),
('Can I save products for later?', 'Absolutely! You can use our Wishlist feature to save your favorite products and easily move them to your cart when you are ready to buy.', true),
('How will I receive order updates?', 'You will receive real-time order updates via email notifications, and you can also track your shipment status directly from the Orders section in your profile.', true),
('What is your return policy?', 'We offer a hassle-free 7-day return policy for eligible products. If an item arrives damaged, you can request a replacement or refund through the support section.', true);
